package gadomancymodern.node;
import java.util.*;
import net.minecraft.util.RandomSource;
import tc4revival.aspect.*;
import tc4revival.content.*;
/** Weighted original node mutations. Addons may register additional outcomes without an enum. */
public class NodeManipulations {
    public static class State {public AspectAmounts base,charge;public AuraNodeType type;public AuraNodeModifier modifier;public boolean growing,allowGrowing;public final AspectCatalog catalog;public State(AspectCatalog catalog,AspectAmounts base,AspectAmounts charge,AuraNodeType type,AuraNodeModifier modifier,boolean growing,boolean allowGrowing){this.catalog=catalog;this.base=base.copy();this.charge=charge.copy();this.type=type;this.modifier=modifier;this.growing=growing;this.allowGrowing=allowGrowing;}}
    public static abstract class Result {public final int weight;public final String effect;public Result(int weight,String effect){if(weight<=0)throw new IllegalArgumentException("Nonpositive mutation weight");this.weight=weight;this.effect=effect;}public boolean accepts(State state){return true;}public abstract boolean apply(State state,RandomSource random);}
    public static final Map<String,Result> RESULTS=new LinkedHashMap<>();
    public static void register(String id,Result result){if(RESULTS.putIfAbsent(id,result)!=null)throw new IllegalArgumentException("Duplicate node mutation: "+id);}
    public static Result choose(State state,RandomSource random,int percent){var choices=new ArrayList<Result>();int total=0,avoidNegative=Math.round(percent/5f);for(var result:RESULTS.values())if(result.accepts(state)&&!(result.effect.equals("negative")&&random.nextInt(100)<avoidNegative)){choices.add(result);total+=result.weight;}if(total==0)return null;int roll=random.nextInt(total);for(var result:choices)if((roll-=result.weight)<0)return result;return null;}
    public static boolean mutate(State state,RandomSource random,int percent){/* Old while(!affect) can hang forever for empty/malformed nodes; retain retries with a finite limit. */for(int tries=0;tries<256;tries++){var chosen=choose(state,random,percent);if(chosen==null)return false;if(chosen.apply(state,random))return true;}return false;}
    public static Aspect combination(AspectCatalog catalog,Aspect a,Aspect b){for(var compound:catalog.compounds()){var c=compound.components();if(c.get(0).equals(a.tag())&&c.get(1).equals(b.tag())||c.get(0).equals(b.tag())&&c.get(1).equals(a.tag()))return compound;}return null;}
    public static void combine(AspectAmounts list,Aspect a,Aspect b,Aspect result,int addition){int lower=Math.min(list.amount(a),list.amount(b));list.remove(a,lower);list.remove(b,lower);list.add(result,lower+addition);}
    static {
        register("gadomancy:break_compound",new Result(4,"negative"){@Override public boolean apply(State s,RandomSource random){for(var aspect:s.base.aspects())if(!aspect.isPrimal()){int amount=s.base.amount(aspect);s.base.remove(aspect);s.charge.remove(aspect);for(var component:aspect.components()){var a=s.catalog.require(component);s.base.add(a,amount);s.charge.add(a,amount);}return true;}return false;}});
        register("gadomancy:combine",new Result(5,"positive"){@Override public boolean apply(State s,RandomSource random){var all=s.base.aspects();if(all.size()<2)return false;if(all.size()==2){var a=all.get(0);var b=all.get(1);var result=combination(s.catalog,a,b);if(result==null)return false;int extra=random.nextInt(4);combine(s.base,a,b,result,extra);combine(s.charge,a,b,result,extra);return true;}int start=random.nextInt(all.size());for(int i=0;i<all.size();i++){var a=all.get((start+i)%all.size());int second=random.nextInt(all.size());for(int j=0;j<all.size();j++){var b=all.get((second+j)%all.size());var result=combination(s.catalog,a,b);if(result!=null){int extra=random.nextInt(4);combine(s.base,a,b,result,extra);combine(s.charge,a,b,result,extra);return true;}}}return false;}});
        register("gadomancy:brighter",new Result(4,"positive"){@Override public boolean accepts(State s){return s.modifier!=AuraNodeModifier.BRIGHT;}@Override public boolean apply(State s,RandomSource random){if(!accepts(s))return false;s.modifier=s.modifier==null?AuraNodeModifier.BRIGHT:s.modifier==AuraNodeModifier.FADING?AuraNodeModifier.PALE:null;return true;}});
        register("gadomancy:dimmer",new Result(5,"negative"){@Override public boolean accepts(State s){return s.modifier!=AuraNodeModifier.FADING;}@Override public boolean apply(State s,RandomSource random){if(!accepts(s))return false;s.modifier=s.modifier==null?AuraNodeModifier.PALE:s.modifier==AuraNodeModifier.BRIGHT?null:AuraNodeModifier.FADING;return true;}});
        register("gadomancy:type",new Result(2,"neutral"){@Override public boolean apply(State s,RandomSource random){var next=s.type;int roll=random.nextInt(40);if(roll>38){if(!s.growing)next=AuraNodeType.HUNGRY;}else if(roll>37)next=AuraNodeType.TAINTED;else if(roll>34)next=AuraNodeType.UNSTABLE;else if(roll>29)next=AuraNodeType.DARK;else if(roll>24)next=AuraNodeType.PURE;else if(roll>14)next=AuraNodeType.NORMAL;boolean changed=next!=s.type;s.type=next;return changed;}});
        register("gadomancy:growing",new Result(1,"positive"){@Override public boolean accepts(State s){return s.allowGrowing;}@Override public boolean apply(State s,RandomSource random){boolean already=s.growing;if(already&&s.type==AuraNodeType.HUNGRY)already=false;if(!already)s.growing=true;return already;/* Original ordinary quirk: first application retries another outcome. */}});
        register("gadomancy:gain_primal",new Result(3,"positive"){@Override public boolean apply(State s,RandomSource random){var primals=s.catalog.primals();if(primals.isEmpty()||s.base.isEmpty())return false;int start=random.nextInt(primals.size());for(int i=0;i<primals.size();i++){var primal=primals.get((start+i)%primals.size());if(s.base.amount(primal)>0)continue;int gain=(int)Math.min(1000000,s.base.total()/(s.base.size()*2L));if(gain<=0)return false;s.base.add(primal,gain);s.charge.add(primal,gain);return true;}return false;}});
    }
}
